// ============================================================================
// CourseCard.jsx - Enterprise Reusable Course Card Component
// -----------------------------------------------------------------------------
// Displays a clean, modern summary of a course and links to CourseDetails.jsx.
// ============================================================================

import React from "react";
import { Link } from "react-router-dom";

export default function CourseCard({ course }) {
  const {
    id,
    title,
    bannerImage,
    shortTagline,
    description,
    priceKES,
    priceUSD,
    courseType,
    deliveryPlatform,
    durationWeeks,
    sessions,
    startDate,
    schedule,
    time,
    certificationEnabled,
    slug,
  } = course;

  const formattedPrice = priceKES
    ? `KES ${priceKES.toLocaleString()} / USD ${priceUSD}`
    : "Free";

  const imageSrc =
    bannerImage || "https://via.placeholder.com/600x400?text=Course+Image";

  const typeColors = {
    zoom: "bg-blue-600",
    lms: "bg-green-600",
    hybrid: "bg-purple-600",
    "online zoom": "bg-indigo-600",
    "online live": "bg-indigo-600",
  };

  const badgeLabel = deliveryPlatform || courseType || "Course";
  const badgeClass =
    typeColors[(deliveryPlatform || courseType || "").toLowerCase()] ||
    "bg-gray-700";

  return (
    <div className="bg-white shadow-md rounded-3xl overflow-hidden hover:shadow-xl transition-all duration-300 border border-gray-200 flex flex-col h-full">
      <div className="aspect-[4/3] w-full overflow-hidden bg-slate-100">
        <img
          src={imageSrc}
          alt={title}
          className="h-full w-full object-cover hover:scale-105 transition-transform duration-300"
        />
      </div>

      <div className="p-6 flex flex-col flex-grow">
        <div className="flex flex-wrap gap-2 mb-4">
          <span
            className={`text-[11px] text-white px-3 py-1 rounded-full uppercase tracking-[0.24em] ${badgeClass}`}
          >
            {badgeLabel}
          </span>
          {certificationEnabled && (
            <span className="text-[11px] bg-teal-700 text-white px-3 py-1 rounded-full uppercase tracking-[0.24em]">
              Certification
            </span>
          )}
        </div>

        <h3 className="text-xl font-bold text-gray-900 mb-3 line-clamp-2">
          {title}
        </h3>

        <p className="text-gray-600 text-sm mb-5 line-clamp-3">
          {shortTagline || description || "No description available."}
        </p>

        <div className="space-y-3 text-sm text-gray-600 mb-6">
          {startDate && (
            <div>
              <span className="font-semibold text-gray-900">Start:</span>{" "}
              {startDate}
            </div>
          )}
          {schedule && (
            <div>
              <span className="font-semibold text-gray-900">Schedule:</span>{" "}
              {schedule}
              {time ? ` - ${time}` : ""}
            </div>
          )}
          {(durationWeeks || sessions) && (
            <div>
              <span className="font-semibold text-gray-900">Duration:</span>{" "}
              {durationWeeks ? `${durationWeeks} weeks` : "TBD"}
              {sessions ? ` - ${sessions} sessions` : ""}
            </div>
          )}
        </div>

        <div className="mt-auto pt-4 border-t border-gray-200">
          <div className="flex items-center justify-between gap-4">
            <span className="text-teal-700 font-semibold">
              {formattedPrice}
            </span>
            <Link
              to={`/courses/${slug || id}`}
              className="inline-flex items-center justify-center px-4 py-2 rounded-full bg-teal-600 text-white text-sm font-semibold hover:bg-teal-700 transition-all duration-300"
            >
              View Course
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}
