import React from "react";
import CourseCard from "./CourseCard";
import { courses } from "../../data/coursesData";

function groupCoursesByCategory(courseList) {
  return courseList.reduce((acc, course) => {
    const category = course.category || "General";
    if (!acc[category]) acc[category] = [];
    acc[category].push(course);
    return acc;
  }, {});
}

function categoryId(category) {
  return category.toLowerCase().replace(/[^a-z0-9]+/g, "-");
}

export default function CourseCatalog() {
  const publishedCourses = courses.filter((course) => course.published);
  const groupedCourses = groupCoursesByCategory(publishedCourses);

  return (
    <section className="bg-white text-gray-900 py-16 px-6 md:px-12 lg:px-20">
      <div className="max-w-6xl mx-auto">
        {Object.entries(groupedCourses).map(([category, items]) => (
          <div key={category} id={categoryId(category)} className="mb-16">
            <div className="mb-10">
              <p className="text-sm uppercase tracking-[0.3em] text-teal-700 mb-3">
                {category}
              </p>
              <h2 className="text-3xl md:text-4xl font-extrabold text-gray-900">
                {category} Courses
              </h2>
              <p className="mt-4 max-w-3xl text-gray-600">
                Explore our current {category.toLowerCase()} offerings designed
                for practical transformation, coaching, and guided
                accountability.
              </p>
            </div>

            <div className="grid gap-8 grid-cols-1 md:grid-cols-2 xl:grid-cols-3">
              {items.map((course) => (
                <CourseCard key={course.id} course={course} />
              ))}
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}
